def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_D = 0
    opp_D = 0
    my_score = 0
    opp_score = 0
    tol = 0
    punish = 0
    unprov = 0

    for i, (m, o) in enumerate(history):
        if m == 'D':
            my_D += 1
        if o == 'D':
            opp_D += 1

        if m == 'C':
            if o == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if o == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

        if i:
            pm = history[i - 1][0]
            if pm == 'D':
                if o == 'C':
                    tol += 1
                elif o == 'D':
                    punish += 1
            if pm == 'C' and o == 'D':
                unprov += 1

    last_m, last_o = history[-1]
    r5_D = sum(1 for i in range(max(0, n - 5), n) if history[i][1] == 'D')
    r10_D = sum(1 for i in range(max(0, n - 10), n) if history[i][1] == 'D')

    hostile = opp_D * 3 > n * 2
    if n >= 20 and r10_D >= 6:
        hostile = True
    if opp_D >= max(8, n // 2):
        hostile = True

    provoked = n >= 2 and history[-2][0] == 'D'
    exploit = (
        n >= 60
        and tol >= 1
        and tol >= punish
        and opp_D * 4 <= n * 3
        and r10_D <= 3
        and unprov <= 2
    )

    if last_o == 'D':
        if hostile:
            return 'D'
        if exploit and unprov >= 2:
            return 'D'
        if provoked and r5_D <= 1 and opp_D <= max(3, n // 15) and unprov <= 1:
            return 'C'
        if exploit:
            p = 0.35 + 0.12 * max(1, tol - punish)
            if n >= 90:
                p += 0.15
            if rng.random() < min(0.75, p):
                return 'D'
        return 'D'

    if hostile:
        if rng.random() < 0.55:
            return 'D'

    if exploit:
        if opp_D == 0:
            return 'D'
        p = 0.55 + 0.12 * max(1, tol - punish)
        if n >= 85:
            p += 0.15
        if n >= 95:
            p += 0.10
        if rng.random() < min(0.95, p):
            return 'D'

    if my_D == 0 and opp_D <= max(1, n // 25) and unprov <= 2:
        if n >= 83:
            return 'D'
        return 'C'

    if my_score + 8 < opp_score:
        if rng.random() < 0.35:
            return 'D'

    if r5_D == 0 and r10_D <= 1:
        return 'C'

    if r5_D >= 2 and rng.random() < 0.35:
        return 'D'

    if r10_D >= 4 and rng.random() < 0.5:
        return 'D'

    if n >= 30 and opp_D > my_D and opp_D * 2 >= n and rng.random() < 0.4:
        return 'D'

    return 'C'
